import { createTraffic } from '../../common/traffic';
import { createBoats } from '../../common/boats';
import { createPeople, type Walker } from '../../common/people';
import { rng, lerp } from '../../common/math';
import { TTL, ttlRoadY, nvtY } from './profile';
import type { TranThiLyBridge } from './TranThiLyBridge';

/* [life] xe (6 làn: 2 làn trong dùng hệ xe chung của khu phố, làn ngoài ở đây), thuyền du lịch, người đi bộ */
export function ttlBuildLife(bridge: TranThiLyBridge) {
  // 2 làn trong mỗi chiều dùng hệ xe chung của scene (PATHS.ttl); làn ngoài (nhiều xe máy) ở đây
  bridge.traffic = createTraffic(bridge, { seed: 731, x0: -1900, x1: 1480, name: 'ttl-traffic',
    lanes: [{ off: TTL.laneOffsets[2], n: 30, speed: 9, bike: 0.85, bus: 0 }] });
  // thuyền du lịch sông Hàn: chạy giữa Cầu Rồng và Trần Thị Lý, qua dưới hai cầu
  bridge.boats = createBoats(bridge, [
    { x: -100, z: -1200, dir: 1, speed: 3.2, len: 24, w: 7, h: 2.6, cab: 3.0, type: 'C' },
    { x: 82, z: 150, dir: -1, speed: 2.8, len: 20, w: 6.5, h: 2.5, cab: 2.8, type: 'A' }
  ], 'ttl-boats');
  // người đi bộ mức chi tiết thấp: trên lề cầu và trên cầu Nguyễn Văn Trỗi (hệ dùng chung common/)
  const rnd = rng(1965), list: Walker[] = [], onDeck = (x: number) => ttlRoadY(x) + 0.25;
  for (let i = 0; i < 46; i++) list.push({ x: lerp(TTL.westEnd + 10, TTL.eastEnd - 10, rnd()), z: (rnd() < 0.5 ? -1 : 1) * (TTL.hw - TTL.sidewalk / 2 - 0.15),
    lo: TTL.westEnd + 5, hi: TTL.eastEnd - 5, dir: rnd() < 0.5 ? -1 : 1, speed: 1 + rnd() * 0.6, profile: onDeck });
  for (let i = 0; i < 34; i++) list.push({ x: lerp(-280, 280, rnd()), z: TTL.nvtZ + (rnd() - 0.5) * 6,
    lo: -285, hi: 285, dir: rnd() < 0.5 ? -1 : 1, speed: 0.9 + rnd() * 0.5, profile: nvtY });
  bridge.people = createPeople(bridge, list, bridge.mats.person, 'ttl-people', rnd);
}
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { rng, lerp } from '../../common/math';
import { createTraffic, stepTraffic, type Traffic, type BridgeVehicle } from '../../common/traffic';
import { createBoats } from '../../common/boats';
import { btCreateFleet, btSetInfo, btSetBoat, btCommit } from '../../environment/boats/fleet';
import { createPeople, type Walker } from '../../common/people';
import { SH, shRoadY } from './profile';
import type { SwingController } from './SwingController';
import type { SongHanBridge } from './SongHanBridge';

/* [life] xe dừng trước barie, người đi bộ, thuyền du lịch, tàu buồm cao chờ mở luồng */
export function shBuildLife(bridge: SongHanBridge) {
  bridge.traffic = createTraffic(bridge, { seed: 2000, x0: -1500, x1: 1480, name: 'sh-traffic',
    lanes: [{ off: SH.lane, n: 26, speed: 11, bike: 0.6, bus: 0.04 }] });
  // thuyền du lịch nối lộ trình Cầu Rồng – Cầu sông Hàn – Cầu Thuận Phước (giữa các làn thuyền chung)
  bridge.boats = createBoats(bridge, [
    { x: 31, z: 700, dir: -1, speed: 3.4, len: 22, w: 7, h: 2.6, cab: 2.9, type: 'A' },
    { x: 41, z: -900, dir: 1, speed: 3.0, len: 18, w: 6.5, h: 2.5, cab: 2.7, type: 'B' }
  ], 'sh-boats');
  // người đi bộ: lề cầu (phần cố định) và lề ven sông Bạch Đằng
  const rnd = rng(2903), list: Walker[] = [], zs = SH.hw - SH.sidewalk / 2 - 0.15;
  for (let i = 0; i < 36; i++) {
    const west = i % 2 === 0, lo = west ? -285 : SH.fixedStart + 8, hi = west ? -SH.fixedStart - 8 : 285;
    list.push({ x: lerp(lo, hi, rnd()), z: (rnd() < 0.5 ? -1 : 1) * zs, lo, hi, dir: rnd() < 0.5 ? -1 : 1, speed: 1 + rnd() * 0.5, profile: (x) => shRoadY(x) + 0.25 });
  }
  for (let i = 0; i < 40; i++) list.push({ x: -276 + (rnd() - 0.5) * 18, z: lerp(-420, 420, rnd()), lo: -420, hi: 420, dir: rnd() < 0.5 ? -1 : 1,
    speed: 0.9 + rnd() * 0.5, axis: 'z', profile: () => CONFIG.landY + 0.05 });
  bridge.people = createPeople(bridge, list, bridge.mats.person, 'sh-people', rnd);
  // tàu buồm cao: cột buồm cao hơn tĩnh không, chỉ qua được khi cầu mở (luồng phía Tây)
  const ship = new THREE.Group(); ship.name = 'sh-tall-ship';
  // một đội tàu 1 chiếc kiểu E (thân, nhà boong, cột, buồm gộp) = 1 lệnh vẽ; group ship vẫn do SongHanBridge di chuyển
  const tall = btCreateFleet(1, ['E'], ship, 'sh-tall-ship-boat');
  btSetInfo(tall, 0, { type: 'E', variant: 0, led: 4, name: 0 });
  btSetBoat(tall, 0, new THREE.Vector3(), new THREE.Quaternion(), 30); btCommit(tall);
  ship.position.set(-36, 0, -260);
  bridge.life.add(ship);
  bridge.ship = { obj: ship, z: -260, target: -260, dir: 1, speed: 4.5 };
}

/* Xe: như hệ chung, nhưng khi không cho vào nhịp quay thì xếp hàng trước barie */
const before: BridgeVehicle[] = [];          // mảng tạm dùng lại (D-018)
let saved = new Float64Array(0);           // tốc độ gốc (double: trả lại đúng từng bit)
const byDist = (a: BridgeVehicle, b: BridgeVehicle) => Math.abs(a.s) - Math.abs(b.s);
export function shStepTraffic(T: Traffic, dt: number, ctrl: SwingController) {
  const bx = SH.barrierX;
  if (!ctrl.allowEntry) {
    for (const dir of [1, -1]) {
      before.length = 0;
      for (const v of T.list) if (v.dir === dir && (dir > 0 ? v.s < -bx : v.s > bx)) before.push(v);
      before.sort(byDist);
      before.forEach((v, r) => { v.hold = bx + 3 + r * 7.5; });
    }
  }
  if (saved.length !== T.list.length) saved = new Float64Array(T.list.length);
  for (let i = 0; i < T.list.length; i++) saved[i] = T.list[i].speed;
  T.list.forEach((v) => {
    if (ctrl.allowEntry || v.hold === undefined) return;
    const stopAt = -v.dir * v.hold, dist = (stopAt - v.s) * v.dir;          // khoảng còn lại tới vị trí dừng
    if (dist <= 0 || (v.dir > 0 ? v.s >= -bx : v.s <= bx)) return;          // đã qua barie thì chạy tiếp
    v.speed = Math.min(v.speed, Math.max(0, dist / Math.max(dt, 1e-3)));
  });
  stepTraffic(T, dt, shRoadY);
  T.list.forEach((v, i) => { v.speed = saved[i]; if (ctrl.allowEntry) delete v.hold; });
}
import * as THREE from 'three';
import { CONFIG } from '../config';
import { scene } from '../core/renderer';
import { MAT } from '../core/materials';
import { rand } from '../common/math';
import { shadowed } from '../common/geometry';
import { deckY } from '../bridges/dragon/profile';

/* ============================ Cây xanh & đèn đường ============================ */
export function buildTrees() {
  const round: [number, number][] = [], palms: [number, number][] = [];
  const B = CONFIG.bankX;
  for (let z = -2300; z < 2300; z += 14) {
    if (Math.abs(z) < 26 || Math.abs(z - CONFIG.ttl.z) < 24) continue;
    for (const s of [-1, 1]) {
      const x = s * (B + 9 + rand() * 12);
      ((Math.round(z / 14) % 3 === 0) ? palms : round).push([x, z]);
    }
  }
  for (const [x0, x1] of [[-1880, -345], [345, 1460]]) for (let x = x0; x < x1; x += 16) {
    for (const s of [-1, 1]) (x > 1200 ? palms : round).push([x + rand() * 3, s * 21.5]);
  }
  for (let i = 0; i < 160; i++) { // công viên hai đầu cầu
    const s = i % 2 ? 1 : -1; round.push([s * (345 + rand() * 120), (rand() < 0.5 ? -1 : 1) * (32 + rand() * 120)]);
  }
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), col = new THREE.Color();
  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.35, 1, 6).translate(0, 0.5, 0);
  const t1 = new THREE.InstancedMesh(trunkGeo, MAT.trunk, round.length);
  const c1 = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 10, 8), MAT.leaf, round.length);
  round.forEach(([x, z], i) => {
    const h = 3 + rand() * 2.5, r = 2.4 + rand() * 1.8;
    m.compose(v.set(x, CONFIG.landY, z), q, s.set(1, h, 1)); t1.setMatrixAt(i, m);
    m.compose(v.set(x, CONFIG.landY + h + r * 0.6, z), q, s.set(r, r * 0.85, r)); c1.setMatrixAt(i, m);
    col.setHSL(0.27 + rand() * 0.06, 0.45, 0.35 + rand() * 0.12); c1.setColorAt(i, col);
  });
  const t2 = new THREE.InstancedMesh(trunkGeo, MAT.trunk, palms.length);
  const c2 = new THREE.InstancedMesh(new THREE.ConeGeometry(1, 1, 9, 1, true), MAT.palm, palms.length);
  palms.forEach(([x, z], i) => {
    const h = 8 + rand() * 4;
