      ((Math.round(z / 14) % 3 === 0) ? palms : round).push([x, z]);
    }
  }
  for (const [x0, x1] of [[-1880, -345], [345, 1460]]) for (let x = x0; x < x1; x += 16) {
    for (const s of [-1, 1]) (x > 1200 ? palms : round).push([x + rand() * 3, s * 21.5]);
