import * as THREE from 'three';
import { CONFIG } from '../../config';
import { MAT } from '../../core/materials';
import { shared, weatherU, windFx } from '../../core/shared';
import { windAt } from './impact';
import type { WeatherParams } from './state';

/* ===== [weather] Gió (mục 4.5): 0 draw call, chỉ uniform + vài hệ số vô hướng =====
   - Cây: vá MAT.leaf, MAT.palm — dịch tán theo hướng gió trong vertex shader, tỉ lệ độ cao điểm trên mặt đất, pha theo vị trí instance.
     Thân (MAT.trunk) và bóng đổ không lắc (depth material mặc định) — chấp nhận.
   - Dây: option `sway` của bridgePatch (common/shaders.ts) đọc uSwayTp/Ttl/Sh; biên độ tính ở đây: TP và SH tăng theo v², TTL theo đường cong mưa–gió.
   - Thuyền, lửa/nước Cầu Rồng, râu rồng, tốc độ sóng: hệ số trong windFx (core/shared.ts), mặc định trung tính.
   Gió = 0 (preset `now`): mọi uniform/hệ số về ĐÚNG giá trị trung tính, nhánh shader không chạy. */
const smooth = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };

function patchTree(mat: THREE.MeshStandardMaterial, key: string) {
  mat.customProgramCacheKey = () => key;
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uTime = shared.uTime; sh.uniforms.uWindDir = weatherU.uWindDir;
    sh.uniforms.uTreeLean = weatherU.uTreeLean; sh.uniforms.uTreeSway = weatherU.uTreeSway;
    const w = CONFIG.weather.wind.trees.omega;
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime; uniform vec2 uWindDir; uniform float uTreeLean; uniform float uTreeSway;')
      .replace('#include <project_vertex>', `#include <project_vertex>
        #ifdef USE_INSTANCING
        if (uTreeLean + uTreeSway > 0.0) {
          vec3 twC = (modelMatrix * vec4(instanceMatrix[3].xyz, 1.0)).xyz;
          float twH = max((modelMatrix * instanceMatrix * vec4(transformed, 1.0)).y - ${CONFIG.landY.toFixed(2)}, 0.0);   // độ cao điểm trên mặt đất
          float twPh = dot(twC.xz, vec2(0.13, 0.17));
          float twG = uTreeLean + uTreeSway * sin(uTime * ${w.toFixed(2)} + twPh);
          float twS = uTreeSway * 0.3 * sin(uTime * ${(w * 1.31).toFixed(2)} + twPh * 2.0);
          vec3 twD = (vec3(uWindDir.x, 0.0, uWindDir.y) * twG + vec3(-uWindDir.y, 0.0, uWindDir.x) * twS) * twH;
          mvPosition.xyz += mat3(viewMatrix) * twD; gl_Position = projectionMatrix * mvPosition;
        }
        #endif`);
  };
  mat.needsUpdate = true;
}

/* Vá shader tán cây (gọi trong buildWeather, trước khung hình đầu). */
export function buildWind() {
  patchTree(MAT.leaf, 'tree-leaf-wind');
  patchTree(MAT.palm, 'tree-palm-wind');
}

/* Mỗi khung: c = thời tiết hiện tại, v = gió tức thời ở 10 m (m/s), on = weather đang bật (false → biên độ dây = 0). */
export function updateWind(c: WeatherParams, v: number, on: boolean) {
  const W = CONFIG.weather.wind, K = on ? CONFIG.weather.swayExaggeration : 0;
  if (c.wind < 1e-3 && c.gust < 1e-3) v = 0;                    // dưới ngưỡng: trung tính chính xác
  const d = weatherU.uWindDir.value; d[0] = Math.cos(c.windDir); d[1] = Math.sin(c.windDir);
  // Hanger TP: tăng theo v², có trần
  const vTp = windAt(W.tp.h, v);
  weatherU.uSwayTp.value = v ? K * Math.min(W.tp.maxAmp, W.tp.amp * (vTp / W.tp.refWind) ** 2) : 0;
  // Dây TTL: rung mưa–gió cực đại khi gió vừa [lo, hi] VÀ có mưa; hết mưa chỉ còn phần gió khô (nhỏ); gió vượt hi (bão) thì gió giật làm dây dao động (buffeting) thay cho rung mưa–gió
  const T = W.ttl, vTtl = windAt(T.h, v);
  const band = smooth(T.lo - 2, T.lo + 1, vTtl) * (1 - smooth(T.hi - 2, T.hi + 4, vTtl)), wetF = smooth(T.rainOn[0], T.rainOn[1], c.rain);
  const buffet = T.buffet * smooth(T.hi, T.hi + T.buffetRise, vTtl);
  weatherU.uSwayTtl.value = v ? K * (T.peak * band * wetF + (T.dryAmp + buffet) * (vTtl / T.refWind) ** 2) : 0;
  // Dây Cầu sông Hàn: như TP, nhỏ hơn
  const vSh = windAt(W.sh.h, v);
  weatherU.uSwaySh.value = v ? K * Math.min(W.sh.maxAmp, W.sh.amp * (vSh / W.sh.refWind) ** 2) : 0;
  // Cây: không phóng đại; nghiêng theo gió trung bình, dao động theo gió tức thời
  const Tr = W.trees;
  weatherU.uTreeLean.value = v ? Math.min(Tr.max, Tr.lean * (c.wind / Tr.refWind) ** 2) : 0;
  weatherU.uTreeSway.value = v ? Math.min(Tr.max, Tr.sway * (v / Tr.refWind) ** 2) : 0;
  // Hệ số CPU: vector gió (m/s), thuyền, râu rồng, tốc độ sóng
  windFx.x = v * d[0]; windFx.z = v * d[1];
  windFx.boatRock = 1 + W.boatRock * v; windFx.whisker = 1 + W.whisker * v; windFx.waveSpeed = 1 + W.waveSpeed * v;
}

/* Biên độ đang hiển thị (m, đã phóng đại) — cho test / bảng ảnh hưởng */
export const swayNow = () => ({ tp: weatherU.uSwayTp.value, ttl: weatherU.uSwayTtl.value, sh: weatherU.uSwaySh.value, treeLean: weatherU.uTreeLean.value, treeSway: weatherU.uTreeSway.value, boatRock: windFx.boatRock });
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { rng } from '../../common/math';
import { scene } from '../../core/renderer';
import { MAT } from '../../core/materials';

/* ===== [weather] Cây đổ sau bão (mục 4.8): 0 draw call, chỉ ghi lại ma trận instance =====
   Cây = cặp InstancedMesh (thân MAT.trunk + tán MAT.leaf / MAT.palm, cùng chỉ số, anh em liền kề trong cùng cha — xem environment/trees.ts).
   Chọn 6–10 cây trong `radius` quanh điểm nhìn (bộ sinh riêng rng(seed + 7), KHÔNG dùng rand()), nghiêng quanh gốc theo hướng gió tới 80° trong fallSec giây.
   LƯU ma trận gốc của đúng những instance đã chọn và ghi lại đúng bản gốc khi dựng cây lại. Instance đã bị dọn scale 0 (hầm, riverfront) bị bỏ qua.
   Chưa đổ → không đụng gì (preset `now` không đổi). */
interface Pair { trunk: THREE.InstancedMesh; crown: THREE.InstancedMesh }
interface Hit { pair: Pair; i: number; trunk0: THREE.Matrix4; crown0: THREE.Matrix4; base: THREE.Vector3; yaw: number }
let pairs: Pair[] = [];
let hits: Hit[] = [], angle = 0, goal = 0, axis = new THREE.Vector3(), rnd = rng(CONFIG.weather.seed + 7);
const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), r = new THREE.Matrix4(), t1 = new THREE.Matrix4();

/* Quét cảnh sau khi mọi cây đã dựng và đã dọn (gọi trong buildWeather) */
export function buildFallen() {
  pairs = [];
  scene.traverse((o) => {
    const crown = o as THREE.InstancedMesh;
    if (!crown.isInstancedMesh || (crown.material !== MAT.leaf && crown.material !== MAT.palm) || !crown.parent) return;
    const sib = crown.parent.children, trunk = sib[sib.indexOf(crown) - 1] as THREE.InstancedMesh | undefined;
    if (trunk && trunk.isInstancedMesh && trunk.material === MAT.trunk && trunk.count === crown.count) pairs.push({ trunk, crown });
  });
}

/* Bản chụp ma trận instance của mọi thân/tán cây (cho test so sánh trước/sau khi dựng lại) */
export const fallenSnapshot = () => pairs.flatMap((p) => [Array.from(p.trunk.instanceMatrix.array), Array.from(p.crown.instanceMatrix.array)]);
export const fallenState = () => ({ pairs: pairs.length, down: hits.length, angle });

/* Ghi ma trận nghiêng quanh gốc: M' = T(gốc)·R(trục, góc)·Ry(lệch · tiến độ)·T(−gốc)·M */
const _R = new THREE.Matrix4(), _out = new THREE.Matrix4();   // tạm cấp sẵn (D-018)
function pose(h: Hit, a: number) {
  const R = _R.makeTranslation(h.base.x, h.base.y, h.base.z)
    .multiply(r.makeRotationAxis(axis, a)).multiply(m.makeRotationY(h.yaw * a / goal)).multiply(t1.makeTranslation(-h.base.x, -h.base.y, -h.base.z));
  h.pair.trunk.setMatrixAt(h.i, _out.multiplyMatrices(R, h.trunk0));
  h.pair.crown.setMatrixAt(h.i, _out.multiplyMatrices(R, h.crown0));
  h.pair.trunk.instanceMatrix.needsUpdate = true; h.pair.crown.instanceMatrix.needsUpdate = true;
}

/* Chọn cây gần `near` và bắt đầu đổ theo hướng gió dir (rad, 0 = +X). Gọi lại khi đang đổ thì bỏ qua. */
export function fellTrees(near: THREE.Vector3, dir: number) {
  if (hits.length || !pairs.length) return;
  const F = CONFIG.weather.fallen, cand: { pair: Pair; i: number; d: number }[] = [];
  for (const p of pairs) for (let i = 0; i < p.crown.count; i++) {
    p.crown.getMatrixAt(i, m); m.decompose(v, q, s);
    if (s.x < 0.01 || s.y < 0.01) continue;                       // đã dọn scale 0
    const d = Math.hypot(v.x - near.x, v.z - near.z);
    if (d < F.radius) cand.push({ pair: p, i, d });
  }
  cand.sort((a, b) => a.d - b.d);
  const pool = cand.slice(0, F.pool), n = Math.min(pool.length, F.count[0] + Math.floor(rnd() * (F.count[1] - F.count[0] + 1)));
  for (let k = 0; k < n; k++) {
    const c = pool.splice(Math.floor(rnd() * pool.length), 1)[0];
    const trunk0 = new THREE.Matrix4(), crown0 = new THREE.Matrix4();
    c.pair.trunk.getMatrixAt(c.i, trunk0); c.pair.crown.getMatrixAt(c.i, crown0);
    hits.push({ pair: c.pair, i: c.i, trunk0, crown0, base: new THREE.Vector3().setFromMatrixPosition(trunk0), yaw: (rnd() - 0.5) * 2 * F.jitter });
  }
  axis.set(0, 1, 0).cross(v.set(Math.cos(dir), 0, Math.sin(dir))).normalize();   // quay quanh trục này một góc dương thì ngọn nghiêng về hướng gió
  angle = 0; goal = F.angleDeg * Math.PI / 180;
}

/* Dựng cây lại: ghi lại ĐÚNG ma trận gốc (so sánh được bằng ===) rồi quên */
export function standTrees() {
  for (const h of hits) {
    h.pair.trunk.setMatrixAt(h.i, h.trunk0); h.pair.crown.setMatrixAt(h.i, h.crown0);
    h.pair.trunk.instanceMatrix.needsUpdate = true; h.pair.crown.instanceMatrix.needsUpdate = true;
  }
  hits = []; angle = 0; goal = 0;
}

/* Mỗi khung: đang đổ thì tăng tiến độ tới 1; góc ∝ tiến độ² (cây đổ nhanh dần). Chưa chọn cây nào thì không làm gì. */
export function updateFallen(dt: number) {
  if (!hits.length || angle >= goal) return;
  angle = Math.min(goal, angle + goal * dt / CONFIG.weather.fallen.fallSec);
  const k = angle / goal;
  for (const h of hits) pose(h, goal * k * k);
}
